import json,re
from pathlib import Path
out=Path('/tmp/compact-demand-results');summary=[]
for seed,suffix in [(7,''),(11,''),(23,''),(11,'-repeat')]:
 runs={label:json.loads((out/f'{label}-{seed}{suffix}.json').read_text()) for label in ['base','compact'] if (out/f'{label}-{seed}{suffix}.json').exists()}
 for label,d in runs.items():
  row=dict(seed=seed,label=label,repeat=bool(suffix),seconds=[b['seconds'] for b in d['batches']],total=sum(b['seconds'] for b in d['batches']),inferences=[b['inferences'] for b in d['batches']],coverage=[r['belief_metrics']['coverage'] for r in d['result']['rounds']],brier=[r['belief_metrics']['brier_score'] for r in d['result']['rounds']],aborts=[b['metrics']['search_aborts'] for b in d['batches']])
  summary.append(row);print(row)
 if len(runs)==2:
  norm=lambda x:re.sub(r'\bkb[0-9a-f]{32}\b','KB',json.dumps(x))
  assert norm([b['answers'] for b in runs['base']['batches']])==norm([b['answers'] for b in runs['compact']['batches']]),seed
  for a,b in zip(runs['base']['batches'],runs['compact']['batches']):
   strip=lambda m:{k:v for k,v in m.items() if k!='wall_seconds'}
   assert strip(a['metrics'])==strip(b['metrics']),(seed,strip(a['metrics']),strip(b['metrics']))
  for a,b in zip(runs['base']['result']['rounds'],runs['compact']['result']['rounds']):
   assert a['beliefs']==b['beliefs'] and a['belief_metrics']==b['belief_metrics'],seed
  assert runs['base']['result']['aggregate']['station_score']==runs['compact']['result']['aggregate']['station_score']
  assert runs['base']['result']['aggregate']['regret']==runs['compact']['result']['aggregate']['regret']
  print('Exact proofs, beliefs and all non-timing query metrics match:',seed)
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
